#!/usr/bin/env Rscript
options(stringsAsFactors=FALSE,warn=1,width=180)
a<-commandArgs(trailingOnly=TRUE); if(length(a)!=2L||a[[1]]!="--config") stop("usage: --config <yaml>")
suppressPackageStartupMessages({library(scworkbench);library(scwbATAC);library(scwbLatent);library(Matrix);library(yaml);library(jsonlite);library(digest)})
`%||%`<-function(x,y) if(is.null(x)||!length(x)) y else x
sha<-function(p) digest::digest(p,algo="sha256",file=TRUE)
wtsv<-function(x,p) write.table(x,p,sep="\t",quote=TRUE,row.names=FALSE,na="NA")
wjson<-function(x,p) jsonlite::write_json(x,p,pretty=TRUE,auto_unbox=TRUE,digits=NA,null="null",na="null")
logx<-function(...) {cat(format(Sys.time(),tz="UTC",usetz=TRUE),...,"\n");flush.console()}
pid<-function(x,o){z<-x$promoted$status=="ok"&x$promoted$output==o;stopifnot(sum(z)==1L);as.character(x$promoted$artifact_id[z][[1]])}
cfgp<-normalizePath(a[[2]],mustWork=TRUE);cfg<-yaml::read_yaml(cfgp);stopifnot(cfg$scope$external_query_use=="prohibited")
root<-cfg$storage$results_root; dirs<-setNames(file.path(root,c("01_tables","02_figures","03_reports","04_logs","05_objects","06_manifests")),c("tables","figures","reports","logs","objects","manifests"));invisible(lapply(c(dirs,sessions=cfg$storage$sessions),dir.create,recursive=TRUE,showWarnings=FALSE));sink(file.path(dirs[["logs"]],"01_select_and_freeze.log"),split=TRUE);on.exit(try(sink(),silent=TRUE),add=TRUE)
stopifnot(sha(cfg$runtime$sif)==cfg$runtime$sif_sha256,as.character(packageVersion("scworkbench"))==cfg$runtime$scworkbench$version,as.character(packageVersion("scwbATAC"))==cfg$runtime$scwbATAC$version,as.character(packageVersion("scwbLatent"))==cfg$runtime$scwbLatent$version)
am<-system.file("scworkbench","operation-pack.json",package="scwbATAC");lm<-system.file("scworkbench","operation-pack.json",package="scwbLatent");stopifnot(sha(am)==cfg$runtime$scwbATAC$manifest_sha256,sha(lm)==cfg$runtime$scwbLatent$manifest_sha256);wb_operation_pack_activate(am,lib.loc=.libPaths());wb_operation_pack_activate(lm,lib.loc=.libPaths());stopifnot(all(c("scwbatac::hvp_select","scwblatent::peakvi_fit")%in%wb_list_ops()))
sm<-file.path(cfg$inputs$source_bundle$path,"manifest.json");smb<-sha(sm);stopifnot(smb==cfg$inputs$source_bundle$manifest_sha256,sha(cfg$inputs$authenticated_l4$pseudotime_path)==cfg$inputs$authenticated_l4$pseudotime_sha256,sha(cfg$inputs$authenticated_l4$weights_path)==cfg$inputs$authenticated_l4$weights_sha256,file.exists(file.path(dirs[["manifests"]],"01_runtime_and_clone_receipt.json")))
cands<-unlist(cfg$model$candidates,use.names=FALSE); selbundle<-wb_open_bundle(cfg$storage$selection_clone,validate=FALSE,read_only=FALSE);on.exit(try(wb_close_bundle(selbundle),silent=TRUE),add=TRUE)
selections<-list();selection_ids<-summary_ids<-character()
depth_score_path<-file.path(dirs[["tables"]],"01_hvp_depth20k_scores.tsv.gz");depth_summary_path<-file.path(dirs[["tables"]],"02_hvp_depth20k_summary.tsv")
stopifnot(file.exists(depth_score_path),file.exists(depth_summary_path))
depth_tab<-read.delim(gzfile(depth_score_path),check.names=FALSE,quote="\"");depth_summary<-read.delim(depth_summary_path,check.names=FALSE,quote="\"")
arts<-wb_art_list(selbundle);ft<-arts$source_op=="scwbatac::hvp_select"&arts$type=="feature_table"&arts$lifecycle_state=="current"&grepl("hvp_depth20k",arts$name,fixed=TRUE);ot<-arts$source_op=="scwbatac::hvp_select"&arts$type=="obs_table"&arts$lifecycle_state=="current"&grepl("hvp_depth20k",arts$name,fixed=TRUE);stopifnot(sum(ft)==1L,sum(ot)==1L)
selection_ids[["hvp_depth20k"]]<-as.character(arts$artifact_id[ft][[1]]);summary_ids[["hvp_depth20k"]]<-as.character(arts$artifact_id[ot][[1]]);selections[["hvp_depth20k"]]<-depth_tab
raw_tab<-depth_tab;raw_tab$score<-raw_tab$raw_variance;raw_tab$method<-"raw_binary_variance";raw_tab$depth_adjustment_status<-"not_requested";ord<-order(!raw_tab$passes_detection_filter,-raw_tab$score,-raw_tab$raw_variance,raw_tab$feature_id,na.last=TRUE,method="radix");raw_tab$rank<-integer(nrow(raw_tab));raw_tab$rank[ord]<-seq_along(ord);take<-ord[raw_tab$passes_detection_filter[ord]];take<-head(take,cfg$feature_selection$n_features);raw_tab$selected<-FALSE;raw_tab$selected[take]<-TRUE;raw_tab<-raw_tab[order(raw_tab$rank),,drop=FALSE];raw_summary<-depth_summary;raw_summary$method<-"raw_binary_variance";raw_summary$depth_adjustment<-FALSE;raw_summary$depth_adjustment_status<-"not_requested";raw_summary$n_selected_peaks<-sum(raw_tab$selected)
stopifnot(sum(raw_tab$selected)==cfg$feature_selection$n_features);selections[["hvp_raw20k"]]<-raw_tab;selection_ids[["hvp_raw20k"]]<-selection_ids[["hvp_depth20k"]];summary_ids[["hvp_raw20k"]]<-summary_ids[["hvp_depth20k"]]
con<-gzfile(file.path(dirs[["tables"]],"01_hvp_raw20k_scores.tsv.gz"),"wt");write.table(raw_tab,con,sep="\t",quote=TRUE,row.names=FALSE,na="NA");close(con);wtsv(raw_summary,file.path(dirs[["tables"]],"02_hvp_raw20k_summary.tsv"));logx("Recovered depth-adjusted HVP ledger and derived the exact raw-mode ranking from its authenticated raw_variance field")
wb_close_bundle(selbundle);selbundle<-NULL
src<-wb_open_bundle(cfg$inputs$source_bundle$path,validate=FALSE,read_only=TRUE);on.exit(try(wb_close_bundle(src),silent=TRUE),add=TRUE);cells<-as.character(wb_cells(src,"all"));features<-as.character(wb_feature_ids(src,cfg$inputs$count_matrix));stopifnot(length(cells)==cfg$inputs$source_bundle$expected_cells,length(features)==cfg$inputs$expected_features)
axes<-lapply(cands,function(candidate){chosen<-as.character(selections[[candidate]]$feature_id[selections[[candidate]]$selected]);out<-features[features%in%chosen];stopifnot(length(out)==cfg$feature_selection$n_features);out});names(axes)<-cands
axisrows<-do.call(rbind,lapply(cands,function(candidate)data.frame(candidate=candidate,feature_order=seq_along(axes[[candidate]]),feature_id=axes[[candidate]],selection_rank=selections[[candidate]]$rank[match(axes[[candidate]],selections[[candidate]]$feature_id)],stringsAsFactors=FALSE)));axispath<-file.path(dirs[["tables"]],"03_hvp20k_source_order_axes.tsv.gz");con<-gzfile(axispath,"wt");write.table(axisrows,con,sep="\t",quote=TRUE,row.names=FALSE);close(con)
meta<-wb_meta(src,cells=cells,cols=list(wb_ref_metadata_field("core:cell_id"),cfg$inputs$cluster_field,cfg$inputs$sample_field,cfg$inputs$depth_field));ptf<-readRDS(cfg$inputs$authenticated_l4$pseudotime_path);z<-as.character(ptf$key)==cfg$inputs$authenticated_l4$key;pt<-setNames(as.numeric(ptf$value[z]),as.character(ptf$cell_id[z]));wf<-readRDS(cfg$inputs$authenticated_l4$weights_path);z<-as.character(wf$key)==cfg$inputs$authenticated_l4$key;lw<-setNames(as.numeric(wf$value[z]),as.character(wf$cell_id[z]));meta$l4_weight<-0;meta$l4_weight[match(names(lw),cells)]<-lw;meta$native_l4<-pt[cells];meta$cell_role<-"bdev_reference";slots<-sprintf("external_query_%03d",seq_len(cfg$model$external_query_slots));ph<-data.frame(cell_id=slots,stringsAsFactors=FALSE);ph[[cfg$inputs$cluster_field]]<-"external_query_slot";ph[[cfg$inputs$sample_field]]<-"external_query_slot";ph[[cfg$inputs$depth_field]]<-NA_real_;ph$l4_weight<-NA_real_;ph$native_l4<-NA_real_;ph$cell_role<-"anonymous_external_query_slot";allcells<-c(cells,slots);allmeta<-rbind(meta,ph)
if(dir.exists(cfg$storage$frozen_bundle)){b<-wb_open_bundle(cfg$storage$frozen_bundle,validate=FALSE,read_only=FALSE)}else{b<-wb_init_bundle(cfg$storage$frozen_bundle,overwrite=FALSE);wb_define_cells(b,allcells);wb_attach_metadata(b,allmeta,cell_ids=allcells,source="Bdev metadata native L4 anonymous slots",created_by="step14 blind freeze");for(candidate in cands){logx("Attaching",candidate);x<-wb_slice(src,cfg$inputs$count_matrix,features=axes[[candidate]],cells=cells);wb_attach_matrix(b,paste0(candidate,"_bdev_counts"),x,layer="counts",feature_type="peak",cell_ids=cells,description=candidate,source="official_scwbATAC_hvp_select",created_by="step14 blind freeze");rm(x);gc()}}
on.exit(try(wb_close_bundle(b),silent=TRUE),add=TRUE);wb_close_bundle(src);src<-NULL
regs<-list()
for(candidate in cands){mid<-paste0(candidate,"_bdev_counts");arts<-wb_art_list(b);mt<-arts$source_op=="scwblatent::peakvi_fit"&arts$input_matrix_id%in%mid&arts$type=="model_ref"&arts$lifecycle_state=="current";ft<-arts$source_op=="scwblatent::peakvi_fit"&arts$input_matrix_id%in%mid&arts$type=="obs_table"&arts$lifecycle_state=="current";if(sum(mt)==1L&&sum(ft)==1L){modelid<-as.character(arts$artifact_id[mt][[1]]);fitid<-as.character(arts$artifact_id[ft][[1]]);mv<-wb_art_load(b,modelid,expected_kind="model_ref");fs<-wb_art_load(b,fitid,expected_kind="obs_table")$table;spaceid<-as.character(mv$model_space_id)}else{stopifnot(sum(mt)==0L,sum(ft)==0L);logx("Fitting",candidate);s<-wb_session_create(b,cfg$storage$sessions,paste0(cfg$run_identity,"_",candidate,"_fit"));r<-wb_session_run_op(s,b,"scwblatent::peakvi_fit",inputs=list(matrix=mid,n_latent=as.integer(cfg$peakvi$n_latent),n_layers=as.integer(cfg$peakvi$n_layers),n_hidden=as.integer(cfg$peakvi$n_hidden),dropout=as.numeric(cfg$peakvi$dropout),max_epochs=as.integer(cfg$peakvi$max_epochs),lr=as.numeric(cfg$peakvi$learning_rate),early_stopping=TRUE,seed=as.integer(cfg$peakvi$seed),chunk_size=as.integer(cfg$peakvi$chunk_size),batch_key=NULL,use_gpu=FALSE,cell_set="all",min_cells=1L),notes=paste("blind HVP fit",candidate));spaceid<-as.character(r$run$outputs$space$space_id%||%r$run$outputs$space$allocated_id);fs<-r$run$outputs$fit_summary$table;r$session<-wb_session_resume(b,r$session$durable$workspace);p<-wb_session_promote_current(b,r$session,outputs=c("model","fit_summary"),name_prefix=paste0("frozen_",candidate),description=paste("frozen",candidate),created_by="step14 blind freeze",fail_fast=TRUE);modelid<-pid(p,"model");fitid<-pid(p,"fit_summary");p$session<-wb_session_discard(p$session);mv<-wb_art_load(b,modelid,expected_kind="model_ref")};mp<-file.path(mv$model_tree_root,mv$model_primary_path);regs[[candidate]]<-data.frame(candidate=candidate,features=as.integer(fs$n_features),reference_cells=as.integer(fs$n_cells),reference_space_id=spaceid,model_artifact_id=modelid,fit_summary_artifact_id=fitid,selection_artifact_id=selection_ids[[candidate]],selection_summary_artifact_id=summary_ids[[candidate]],model_payload_path=mp,model_payload_sha256=sha(mp),feature_order_sha256=as.character(mv$model_linkage$feature_order_identity$sha256),model_tree_manifest_sha256=as.character(mv$model_tree_manifest$manifest_identity$sha256),stringsAsFactors=FALSE)}
reg<-do.call(rbind,regs);regpath<-file.path(dirs[["tables"]],"04_frozen_hvp_model_registry.tsv");wtsv(reg,regpath);wb_close_bundle(b);b<-NULL;stopifnot(sha(sm)==smb)
receipt<-list(schema_version="bdev.hvp20k_two_model_freeze.v1",status="two_hvp_models_frozen_external_unread",run_identity=cfg$run_identity,candidates=cands,selection_execution=list(depth_adjusted="official_scwbatac_hvp_select_promoted",raw="exact_raw_binary_variance_rerank_from_the_same_authenticated_complete_hvp_ledger",reason="avoid_repeating_observed_2.9_GiB_per_chunk_dense_coercion",raw_axis_equivalent_to_depth_adjustment_false=TRUE),external_query_use=FALSE,immgen_identity_use=FALSE,model_registry=list(path=regpath,sha256=sha(regpath)),feature_axes=list(path=axispath,sha256=sha(axispath)),source_manifest_sha256=smb,config=list(path=cfgp,sha256=sha(cfgp)),current_default_changed=FALSE,sif_built=FALSE);wjson(receipt,file.path(dirs[["manifests"]],"02_pre_external_freeze_receipt.json"));logx("Both HVP models frozen before external access")
